    /// <summary>
    /// This structure contains the attributes that determine the goal of the SLO. Interval -&gt; (tagged union structure) The time period used to evaluate the SLO. It can be either a calendar interval or rolling interval. If you omit this parameter, a rolling interval of 7 days is used. NOTE: This is a Tagged Union structure. Only one of the following top level keys can be set: RollingInterval, CalendarInterval. RollingInterval -&gt; (structure) If the interval is a rolling interval, this structure con- tains the interval specifications. DurationUnit -&gt; (string) [required] Specifies the rolling interval unit. Possible values: o MINUTE o HOUR o DAY o MONTH Duration -&gt; (integer) [required] Specifies the duration of each rolling interval. For ex- ample, if Duration is 7 and DurationUnit is DAY , each rolling interval is seven days. Constraints: o min: 1 CalendarInterval -&gt; (structure) If the interval is a calendar interval, this structure con- tains the interval specifications. StartTime -&gt; (timestamp) [required] The date and time when you want the first interval to start. Be sure to choose a time that configures the in- tervals the way that you want. For example, if you want weekly intervals starting on Mondays at 6 a.m., be sure to specify a start time that is a Monday at 6 a.m. When used in a raw HTTP Query API, it is formatted as be epoch time in seconds. For example: 1698778057 As soon as one calendar interval ends, another automati- cally begins. DurationUnit -&gt; (string) [required] Specifies the calendar interval unit. Possible values: o MINUTE o HOUR o DAY o MONTH Duration -&gt; (integer) [required] Specifies the duration of each calendar interval. For ex- ample, if Duration is 1 and DurationUnit is MONTH , each interval is one month, aligned with the calendar. Constraints: o min: 1 AttainmentGoal -&gt; (double) The threshold that determines if the goal is being met. If this is a period-based SLO, the attainment goal is the per- centage of good periods that meet the threshold requirements to the total periods within the interval. For example, an attain- ment goal of 99.9% means that within your interval, you are tar- geting 99.9% of the periods to be in healthy state. If this is a request-based SLO, the attainment goal is the per- centage of requests that must be successful to meet the attain- ment goal. If you omit this parameter, 99 is used to represent 99% as the attainment goal. WarningThreshold -&gt; (double) The percentage of remaining budget over total budget that you want to get warnings for. If you omit this parameter, the de- fault of 50.0 is used. Shorthand Syntax: Interval={RollingInterval={DurationUnit=string,Duration=integer},CalendarInterval={StartTime=timestamp,DurationUnit=string,Duration=integer}},AttainmentGoal=double,WarningThreshold=double JSON Syntax: { "Interval": { "RollingInterval": { "DurationUnit": "MINUTE"|"HOUR"|"DAY"|"MONTH", "Duration": integer }, "CalendarInterval": { "StartTime": timestamp, "DurationUnit": "MINUTE"|"HOUR"|"DAY"|"MONTH", "Duration": integer } }, "AttainmentGoal": double, "WarningThreshold": double }
    /// </summary>
    [CliOption("--goal")]
    public string? Goal { get; set; }

    /// <summary>
    /// A list of key-value pairs to associate with the SLO. You can asso- ciate as many as 50 tags with an SLO. To be able to associate tags with the SLO when you create the SLO, you must have the cloud- watch:TagResource permission. Tags can help you organize and categorize your resources. You can also use them to scope user permissions by granting a user permis- sion to access or change only resources with certain tag values. Constraints: o min: 0 o max: 200 (structure) A key-value pair associated with a resource. Tags can help you organize and categorize your resources. Key -&gt; (string) [required] A string that you can use to assign a value. The combination of tag keys and values can help you organize and categorize your resources. Constraints: o min: 1 o max: 128 Value -&gt; (string) [required] The value for the specified tag key. Constraints: o min: 0 o max: 256 Shorthand Syntax: Key=string,Value=string ... JSON Syntax: [ { "Key": "string", "Value": "string" } ... ]
    /// </summary>
    [CliOption("--tags", GroupValues = true)]
    public IEnumerable<string>? Tags { get; set; }

    /// <summary>
    /// Use this array to create burn rates for this SLO. Each burn rate is a metric that indicates how fast the service is consuming the error budget, relative to the attainment goal of the SLO. Constraints: o min: 0 o max: 10 (structure) This object defines the length of the look-back window used to calculate one burn rate metric for this SLO. The burn rate mea- sures how fast the service is consuming the error budget, rela- tive to the attainment goal of the SLO. A burn rate of exactly 1 indicates that the SLO goal will be met exactly. For example, if you specify 60 as the number of minutes in the look-back window, the burn rate is calculated as the following: burn rate = error rate over the look-back window / (100% - attainment goal percentage) For more information about burn rates, see Calculate burn rates . LookBackWindowMinutes -&gt; (integer) [required] The number of minutes to use as the look-back window. Constraints: o min: 1 o max: 10080 Shorthand Syntax: LookBackWindowMinutes=integer ... JSON Syntax: [ { "LookBackWindowMinutes": integer } ... ]
    /// </summary>
    [CliOption("--burn-rate-configurations", GroupValues = true)]
    public IEnumerable<string>? BurnRateConfigurations { get; set; }

    /// <summary>
    /// Set this to true to create a recommended SLO out of the box. When set to true , you don't need to specify the MetricThreshold or Com- parisonOperator in the SliConfig or RequestBasedSliConfig . The de- fault value is false . This is supported for SLOs on a service, service operation, or a de- pendency.
    /// </summary>
    [CliFlag("--create-recommended-slo", NegatedName = "--no-create-recommended-slo")]
    public bool? CreateRecommendedSlo { get; set; }

    /// <summary>
    /// Indicates whether DevOps Agent will automatically investigate this SLO when it is breached
    /// </summary>
    [CliFlag("--auto-investigation-enabled", NegatedName = "--no-auto-investigation-enabled")]
    public bool? AutoInvestigationEnabled { get; set; }

    [CliOption("--cli-input-json")]
    public string? CliInputJson { get; set; }

    [CliOption("--generate-cli-skeleton")]
    public string? GenerateCliSkeleton { get; set; }

    /// <inheritdoc />
    IEnumerable<ValidationResult> IValidatableObject.Validate(ValidationContext validationContext)
    {
        if (_requiresAlternateInput && !(!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input"))
        {
            yield return new ValidationResult("An alternate input must remain selected for an instance created without required operation values.");
            yield break;
        }

        if (!string.IsNullOrWhiteSpace(CliInputJson) || GenerateCliSkeleton is "input" or "yaml-input")
        {
            yield break;
        }

        yield break;
    }

